let chat = $node["When chat message received"].json;

if (chat.body) {
  chat = chat.body;
}

return [{
  json: {
    from: chat.sessionId || "",
    text: chat.chatInput || "",
    channel: 'chatbot'
  }
}];

const wa = $node["WhatsApp Incoming Webhook"].json;

let messageData = wa.body?.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
let from, text;

if (messageData) {
  from = messageData.from || "";
  text = messageData.text?.body || "";
} else {
  from = wa.from || "";
  text = wa.message || "";
}

return [{
  json: {
    from,
    text,
    channel: 'whatsapp'
  }
}];

const email = $json;

const bodyHtml = email.textAsHtml || '';
const bodyText = bodyHtml.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

return [{
  json: {
    from: email.from?.value?.[0]?.address || '',
    subject: email.subject || '',
    text: bodyText, 
    labelIds: email.labelIds || []
  }
}];

function generateObjectId() {
  return Math.floor(Date.now() / 1000).toString(16) +
    "xxxxxxxxxxxxxxxx".replace(/[x]/g, () =>
      (Math.floor(Math.random() * 16)).toString(16)
    );
}

const results = [];
for (const item of items) {
  const message = item.json.output || item.json || {};
  const rawText = (message.text || message.body || message.content || '').trim();
  const subject = (message.subject || '').trim();
  const full = `${subject} ${rawText}`.trim();

  function findEmail(text, message) {
    if (message.to && /^[\w.%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(message.to)) {
      return message.to;
    }
    const m = text.match(/[a-zA-Z0-9._%+-]+@[a-zA-Z0-9.-]+\.[A-Za-z]{2,}/);
    return m ? m[0] : '';
  }

  function findPhone(text) {
    const m = text.match(/\b(?:\+91[-\s]?)?[6-9]\d{9}\b/);
    return m ? m[0] : '';
  }

  function findName(text) {
    let m = text.match(/\b(?:my name is|this is|i am|i'm|im)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2})/i);
    if (m) return m[1].trim();
    m = text.match(/\bname[:\-]\s*([A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2})/i);
    if (m) return m[1].trim();
    m = text.match(/^(?:hi|hello|hey)[,\s]*([A-Z][a-z]+(?:\s+[A-Z][a-z]+){0,2})/i);
    if (m) return m[1].trim();
    return '';
  }

  function findAddress(text) {
    const m = text.match(/\b(?:address|location|place)\s*(?:is|:)?\s*(.+)/i);
    if (m) {
      let addr = m[1].trim();
      addr = addr.split(/(?:phone|number|email|mail|name)\b/i)[0].trim();
      return addr;
    }
    return '';
  }

  const channelValue = message.channel === 'email' ? 'Email' : (message.channel || '');

  results.push({
    json: {
      user_id: generateObjectId(),
      from: message.from || '',
      text: rawText,
      channel: channelValue || '',
      subject: message.subject || '',
      category: message.category || '',
      email: findEmail(full, message),
      number: findPhone(full) || message.number || '',
      name: findName(full) || message.name || '',
      address_value: findAddress(full) || message.address_value || ''
    }
  });
}

return results;

