let output = $json.output;
let parsed;

try {
  parsed = JSON.parse(output.replace(/^json\s*/, '')); 
} catch {
  parsed = { body: output };
}

let content = parsed.body || parsed;
const channel = (parsed.channel || $('Build AI Agent Payload').first().json.channel || "").toLowerCase();


if (channel === 'email') {

  content = content.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
  content = content
    .split('\n\n')
    .map(p => `<p>${p.trim().replace(/\n/g, '<br>')}</p>`)
    .join('');

} else if (channel === 'whatsapp') {

  content = content.replace(/\*\*(.*?)\*\*/g, '*$1*');

} else {

  content = content.replace(/\*\*(.*?)\*\*/g, '$1');
  content = content.replace(/\*(.*?)\*/g, '$1');
  content = content.replace(/__(.*?)__/g, '$1');
  content = content.replace(/_(.*?)_/g, '$1');
}

return [{
  json: {
    content: content,
    subject: parsed.subject || $('Build AI Agent Payload').first().json.subject || "",
    channel: parsed.channel || $('Build AI Agent Payload').first().json.channel || "",
    category: parsed.category || $('Build AI Agent Payload').first().json.category || "",
    user_id: parsed.to || $('Extract Contact & Address Details').first()?.json?.user_id || "",
    role: 'assistant'
  }
}];

const aiResponse = $json.content || '';


let parsedResponse;
try {
  parsedResponse = JSON.parse(aiResponse);
} catch (e) {

  parsedResponse = {
    to: $json.user_id || '',
    subject: $json.subject || '',
    body: aiResponse,
    channel: ($json.channel || '').toLowerCase(),
    category: ''
  };
}


let formattedBody = parsedResponse.body;
if (parsedResponse.channel === 'email') {
  formattedBody = parsedResponse.body
    .split('\n\n')
    .map(p => `<p>${p.trim().replace(/\n/g, '<br>')}</p>`)
    .join('');
}




return [{
  json: {
    to: parsedResponse.to,
    subject: parsedResponse.subject,
    body: formattedBody,
    channel: parsedResponse.channel,
    category: parsedResponse.category
  }
}];

return {
  json: {
    session_id:$('Merge Channels Input').first().json.from ||"",
    messages: [
      {
        role: "user",
        content: $('Build AI Agent Payload').first().json.body|| $json.text || ""
      },
      {
        role: "assistant",
        content:
          typeof $json.output === "string"
            ? $json.output
            : ($json.output?.output || "")
      }
    ]
  }
};
